--    · 共用密码：demo@123456（哈希由后端 POST /auth/register 真实生成，不是手工伪造）
--    · 用户名统一用 demo 前缀，方便一条 SQL 清理干净：
--        DELETE FROM `user` WHERE username LIKE 'demo%';
