;

-- 让数据看起来自然：注册时间按天散开（约 100 天），并让每 7 个里有 1 个处于禁用状态
UPDATE `user`
SET create_time = DATE_ADD('2026-06-01 09:00:00', INTERVAL (CAST(SUBSTRING(username, 6) AS UNSIGNED) - 1) DAY),
    update_time = DATE_ADD('2026-06-01 09:00:00', INTERVAL (CAST(SUBSTRING(username, 6) AS UNSIGNED) - 1) DAY),
    status      = IF(CAST(SUBSTRING(username, 6) AS UNSIGNED) % 7 = 0, 0, 1)
WHERE username LIKE 'demo%';